# Parse input from prompt
line0 = "3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3"
row0 = [int(x) for x in line0.split()]
print(f"Row 0: {row0}, len={len(row0)}")

# Build the 17x23 input grid from prompt
inp = []
for i in range(17):
    row = []
    if i == 0 or i == 1 or i == 2 or i == 3:
        # All 3s
        row = [3] * 23
    elif i == 4:
        # Row 4: 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 3 8 3 3 3
        # Count: positions 0-18 are 3, position 19 is 8, positions 20-22 are 3
        row = [3]*19 + [8] + [3]*4
    elif i == 5:
        # Row 5: 3 3 3 3 3 2 3 3 6 7 3 3 3 8 3 3 3 3 3 3 3 3 3
        row = [3,3,3,3,3,2,3,3,6,7,3,3,3,8,3,3,3,3,3,3,3,3,3]
    elif i == 6:
        # Row 6: 3 3 3 3 3 0 4 4 2 2 3 3 3 3 3 3 3 3 3 3 3 3 3
        row = [3,3,3,3,3,0,4,4,2,2,3,3,3,3,3,3,3,3,3,3,3,3,3]
    elif i == 7:
        # Row 7: 3 3 3 3 3 2 6 0 4 3 3 3 3 3 3 3 3 3 3 3 3 3 3
        row = [3,3,3,3,3,2,6,0,4,3,3,3,3,3,3,3,3,3,3,3,3,3,3]
    elif i == 8:
        # Row 8: 3 3 3 3 3 3 7 7 6 3 3 3 3 3 3 3 3 3 3 3 3 3 3
        row = [3,3,3,3,3,3,7,7,6,3,3,3,3,3,3,3,3,3,3,3,3,3,3]
    elif i == 9:
        # Row 9: 3 3 3 3 3 3 3 2 3 3 3 3 3 3 3 3 3 3 3 3 8 3 3
        row = [3,3,3,3,3,3,3,2,3,3,3,3,3,3,3,3,3,3,3,3,8,3,3]
    else:
        # Rows 10-16: all 3s
        row = [3] * 23
    inp.append(row)

# Find all non-background (non-3) cells
markers = []
for r in range(17):
    for c in range(23):
        if inp[r][c] != 3:
            markers.append((r, c, inp[r][c]))

print(f"\nFound {len(markers)} markers:")
for r, c, v in markers:
    print(f"  ({r},{c}) = {v}")

# Apply transformation: (r+2, c+2)
output = [[3]*23 for _ in range(17)]
for r, c, v in markers:
    nr, nc = r+2, c+2
    if 0 <= nr < 17 and 0 <= nc < 23:
        output[nr][nc] = v
    else:
        print(f"  Marker ({r},{c},{v}) would go to ({nr},{nc}) - OUT OF BOUNDS!")

# Print output
print("\nOutput grid:")
for r in range(17):
    row_str = ' '.join(str(x) for x in output[r])
    print(f"Row {r}: {row_str}")

